#nullable enable
using Alba;
using Campaigns.Contracts;
using Campaigns.Slices.Campaigns;
using Microsoft.AspNetCore.Mvc;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Slices.Campaigns;

/// <summary>
/// Pattern: command. Status: ready. One command, two possible events — which is why two of the three GWTs
/// share a GIVEN and a WHEN and differ only in the THEN.
/// </summary>
public sealed class RecordOutcomeTests(AppFixture fixture) : IntegrationContext(fixture)
{
    /// <summary>GIVEN a message has been queued. History, appended straight to the stream.</summary>
    private async Task<Guid> Queued(Guid? messageId = null)
    {
        var id = messageId ?? SeedData.MessageId;
        await Given(id, new MessageQueued(
            id, SeedData.CampaignId, QueueMessageTests.SenderId, "Subject",
            QueueMessageTests.TwoRecipients, SeedData.SeededAt));
        return id;
    }

    private async Task<(bool Ok, string? Rule)> Record(
        Guid messageId, string recipient, string outcome, string? reason = null)
    {
        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new RecordOutcome(messageId, recipient, outcome, reason))
                .ToUrl($"/messages/{messageId}/outcome");
            x.IgnoreStatusCode();
        });

        if (result.Context.Response.StatusCode == 204) return (true, null);
        return (false, (await result.ReadAsJsonAsync<ProblemDetails>())?.Title);
    }

    // a delivery is recorded
    //   GIVEN MessageQueued
    //   WHEN  RecordOutcome
    //   THEN  MessageDelivered
    [Fact]
    public async Task ADeliveryIsRecorded()
    {
        var messageId = await Queued();

        var (ok, rule) = await Record(messageId, "a@example.com", RecordOutcomeEndpoint.Delivered);

        ok.ShouldBeTrue(rule);
        (await EventsFor(messageId)).Last().ShouldBeOfType<MessageDelivered>()
            .Recipient.ShouldBe("a@example.com");
    }

    // a bounce is recorded
    //   GIVEN MessageQueued
    //   WHEN  RecordOutcome
    //   THEN  MessageBounced
    [Fact]
    public async Task ABounceIsRecorded()
    {
        var messageId = await Queued();

        var (ok, rule) = await Record(
            messageId, "b@example.com", RecordOutcomeEndpoint.Bounced, "mailbox full");

        ok.ShouldBeTrue(rule);
        (await EventsFor(messageId)).Last().ShouldBeOfType<MessageBounced>()
            .Reason.ShouldBe("mailbox full");
    }

    // an outcome for a recipient not on the message is refused
    //   GIVEN MessageQueued
    //   WHEN  RecordOutcome
    //   THEN  error: NotARecipient    (enforce="aggregate")
    [Fact]
    public async Task AnOutcomeForARecipientNotOnTheMessageIsRefused()
    {
        var messageId = await Queued();

        var (ok, rule) = await Record(messageId, "stranger@example.com", RecordOutcomeEndpoint.Delivered);

        ok.ShouldBeFalse();
        rule.ShouldBe("NotARecipient");
        (await EventsFor(messageId)).OfType<MessageDelivered>().ShouldBeEmpty();

        // Both sides of the boundary. "Refused" on its own would pass just as well against a check that
        // refuses everything.
        (await Record(messageId, "a@example.com", RecordOutcomeEndpoint.Delivered)).Ok.ShouldBeTrue();
    }
}
